/*
|--------------------------------------------------------------------------
| Computer Science core — spoken interview questions for the Mock AI Interview.
|--------------------------------------------------------------------------
|
| Six stacks (DBMS, Operating Systems, Computer Networks, OOP, Data Structures & Algorithms, Software Engineering), three rounds of six
| questions each: the subjects every CSE / IT campus-placement interview asks. Written for this product as the questions an interviewer
| actually speaks, each with the key points a good answer covers (the `note`, which is the rubric the AI scorer is given).
|
| Original wording, written by AptRun and not yet reviewed by a faculty member: every question is flagged needs_review so staff can filter
| and review them (Admin -> Mock interview questions). Idempotent: MockInterviewQuestionsSeeder keys rows by (stack, round, position).
|
| Shape: stack_key => [round_number => [ {text, category, duration_seconds, note, topic, needs_review, origin} ]]
|
*/

$q = fn (string $text, string $note, string $topic, int $seconds = 150, string $category = 'technical') => [
    'text' => $text,
    'category' => $category,
    'duration_seconds' => $seconds,
    'note' => $note,
    'topic' => $topic,
    'needs_review' => true,
    'origin' => 'generated',
];

return [

    // ───────────────────────────── DBMS ─────────────────────────────
